  str_quest_base_story_click_lock_chapter = "Complete quests in the previous Plot to unlock",
  str_quest_base_desc_101 = "Soroz, this is the beginning of your voyage. Unexpected gains, changes, silver linings, and growth... Becoming stronger is always accompanied by anguish. If you can't escape it, embrace it. Your sufferings will not be for nothing.\n—Bethlehem",
  str_quest_base_desc_102 = "Arriving into the world is a profound experience, isn't it? I hope that you deal with crises calmly and rationally, cherishing your bonds. Everyone and everything you see is a part of Astral, and will ultimately become a part of Aurora, even a part of yourself... Accept, understand, respond, and continue growing.\n—Bethlehem",
  str_quest_base_desc_103 = "Echoes from the past reverberate once more, with compatriots, enemies, and comrades in arms pouring in. Prepare yourself for the worst and hope for the best. Weigh your personal hatred against the mission of your new group. These lessons can only be learned through blood and tears.\n—Bethlehem",
  str_quest_base_desc_104 = "Now, do you understand your goal? Do you feel a sense of identity from people outside your group? Ahead lies the last Aurorian city, a floating island in the sky. There, you'll find new bonds, and take a more determined step towards the journey of overcoming darkness.\n—Bethlehem",
  str_quest_base_desc_105 = "Constantly thwarted yet constantly fighting on, like a beast who never knows how to retreat, like a brave man who wielded his sword but died in a forsaken land. The past will keep advancing, bringing you face to face with your greatest fears. Look at her face and tell me: Who do you see?\n—Bethlehem",
  str_quest_base_desc_106 = "Anxious? As the Aurora suggests, you are near the bottom, a quagmire of bitterness and resentment, an iron prison built of failure and humiliation. But only here can you find true strength—not steel and iron, but wide vision and an inclusive mind.\n—Bethlehem",
  str_quest_base_desc_107 = "We're finally entering a new phase of our interspace conversation, Caelestite. You would never understand my role, neither could I the fragments of words written as vague omens. Aurora is dimming, and desperate men with outstretched wings fill the skies of Lumopolis. Either you conquer it or be conquered, end of story.\n—Bethlehem",
  str_quest_base_desc_108 = "Even in the deepest, darkest chasm, you will survive to see the fulfillment of the prophecy. That's what I believe, and my intuition insists that I follow. Seize the opportunity, Caelestite, and condemn the black keep back to where it belonged!\n—Bethlehem",
  str_quest_base_desc_109 = "We have two homes: The one beneath your feet, and the one in your heart. The fortunate among us will find that there is no difference between them. However, most souls must endure a constant conflict between the two, and may even be left without hope of once again placing their feet on the land deep in their memories. Even if the heart is unwilling to go on, there is no other way.\n                                                                                                                       —Bethlehem",
  str_quest_base_desc_110 = "I believe that land will allow you to grow, reminding you of many things while allowing you to calmly make your peace with them. The end of your journey lies ahead. Cast off your resentment and hatred, and let it disappear. I hope that when we next meet, you will be a new you.\n                                                                                                                       —Bethlehem",
  str_quest_base_desc_111 = "Eternal night, the territory no Aurorian wants to be close to, is an abyss eroded by darkness. At this Twilight Interlude, seize the fleeting opportunity, master of the Colossus, to break through the dark. May your wish be fulfilled.\n\n—Bethlehem",
  str_quest_base_desc_112 = "Hope is often accompanied by trials, like a flower covered with thorns. If you are prepared to be bruised and battered, go back to where you started. To seek, to lose, to despair, and finally, to lift your head once again.\n\n—Bethlehem",
  str_quest_base_desc_113 = "The blade of truth pierces through one's chest, tearing to pieces the fragile heart within. \"How can this be?\" \"It can't be!\" Shock, doubt, resent, and then staring into the void beside the lost abyss. I can't see your choice, Caelestite, I can't see anything.\n\n——Bethlehem",
  str_quest_base_desc_114 = "Everyone is constantly seeking knowledge in their life. You are fortunate, yet also pitiful. Fate has afforded you more room to explore. You can go further than most people, but it's a lonely journey. I don't know where you'll end up, because your destination lies beyond what I can see.\n—Bethlehem",
  str_quest_base_desc_115 = "Have you noticed that you are starting to meet more and more people? They have different origins and destinations, yet their paths coincide with yours at a certain juncture. So many people live under the sky. The lucky ones with the sun above their heads are bathed in the most abundant sunlight, but those who stand in the twilight are the farthest from the sun.\n—Bethlehem",
  str_quest_base_desc_116 = "What an ironic twist of fate this is that forces you to be along with an old enemy. Whether a sea of flames or a deep pit is ahead, there's no choice but to face it with your friends.\n—Bethlehem",
  str_quest_base_desc_117 = "The battlefield is a stage for schemers, and ignorant spectators flock to it from all directions. The boundless night approaches, yet Aurorian have not woken up from their sweet dreams.\n—Bethlehem",
  str_quest_base_desc_118 = "Amidst the shifting tides of power, those overlooked by fate rise onto the world stage under the gaze of many. Yet, ambition proves the most futile weapon on the battlefield: only by slaying one's former self can one escape from the whirlpool of politics and gain a rekindled life.\n—Bethlehem",
  str_quest_base_desc_119 = "Is strength derived from self-propulsion or the bestowal of others? Until you witness mighty forms struggling in the mire, digging their own graves, you'll finally realize fragility is the essence of life.\n—Bethlehem",
  str_quest_base_desc_120 = "A foreign existence finally made contact with Illumina after more than 600 years. Should we turn the pages of history books to search for possibilities, or should we abandon the past and forge a new path? That is the question at hand, as well as a conundrum that has troubled countless generations of Aurorians.\n—Bethlehem",
  str_quest_base_desc_121 = "You've spent countless hours of happiness with your friends, but you never thought that the time to say goodbye would come upon you so hastily. The signal from the past has returned. This time, you must become strong and explore your past in the unknown ruins.\n—Bethlehem",
  str_quest_base_desc_122 = "\"To erect beacons along the path ahead,\" thus spoke I, the Queen of the North.\n—Bethlehem",
