  str_quest_base_achieve_type_401_space = "Wealth",
  str_quest_base_achieve_type_501_space = "Relationships",
  str_quest_base_achieve_type_406_space = "Aurorian",
  str_quest_base_achieve_type_200_space = "Adventure",
  str_quest_base_achieve_type_407_space = "Colossus",
  str_quest_base_achieve_finish_list_title = "Completed Quests",
  str_quest_base_desc_123 = "You have now witnessed the eternal night—have you solidified the resolve in your heart? Countless souls are stuck in a stalemate of shadows, chasing after a fleeting hope. But for you, that hope is real.\nYou will seize it, for this tale begins with your first steps as a hero. You shall guard that spark of hope, and in return, it will endure because of you. Believe in this, and press forward with unshakable faith.\n—Bethlehem",
